// Remembers this browser's G across reloads without leaving it readable in
// localStorage. G is encrypted with AES-GCM; the key is generated by the
// browser as non-extractable and lives in IndexedDB, so the localStorage value
// is only ciphertext and the key bytes can't be copied out.

import { randomG } from "./constant.js";

const LS_KEY = "orbitlab.g";
const OLD_KEYS = ["orbitlab.s", "orbitlab.session"]; // earlier builds
const DB_NAME = "orbitlab";
const STORE = "keys";

function openDb() {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open(DB_NAME, 1);
    req.onupgradeneeded = () => req.result.createObjectStore(STORE);
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

function idb(db, mode, fn) {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE, mode);
    const req = fn(tx.objectStore(STORE));
    tx.oncomplete = () => resolve(req.result);
    tx.onerror = () => reject(tx.error);
  });
}

async function getKey(create) {
  const db = await openDb();
  try {
    let key = await idb(db, "readonly", (s) => s.get("k"));
    if (!key && create) {
      key = await crypto.subtle.generateKey({ name: "AES-GCM", length: 256 }, false, ["encrypt", "decrypt"]);
      await idb(db, "readwrite", (s) => s.put(key, "k"));
    }
    return key || null;
  } finally {
    db.close();
  }
}

const toB64 = (buf) => btoa(String.fromCharCode(...new Uint8Array(buf)));
const fromB64 = (s) => Uint8Array.from(atob(s), (c) => c.charCodeAt(0));

async function encrypt(text) {
  const key = await getKey(true);
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const ct = await crypto.subtle.encrypt({ name: "AES-GCM", iv }, key, new TextEncoder().encode(text));
  const out = new Uint8Array(12 + ct.byteLength);
  out.set(iv);
  out.set(new Uint8Array(ct), 12);
  return toB64(out);
}

async function decrypt(blob) {
  const key = await getKey(false);
  if (!key) return null;
  const raw = fromB64(blob);
  const pt = await crypto.subtle.decrypt({ name: "AES-GCM", iv: raw.slice(0, 12) }, key, raw.slice(12));
  return new TextDecoder().decode(pt);
}

export async function saveG(g) {
  try {
    localStorage.setItem(LS_KEY, await encrypt(String(g)));
  } catch {
    /* storage or WebCrypto unavailable: G lives in memory for this tab only */
  }
}

/** This browser's saved G, or a freshly drawn (and saved) one. */
export async function loadOrCreateG() {
  try {
    for (const k of OLD_KEYS) localStorage.removeItem(k);
    const blob = localStorage.getItem(LS_KEY);
    if (blob) {
      const g = Number(await decrypt(blob));
      if (g > 0 && Number.isFinite(g)) return g;
    }
  } catch {
    /* unreadable or tampered with: draw a new one */
  }
  const g = randomG();
  await saveG(g);
  return g;
}
